class ListingDetailScreen extends StatefulWidget {
  const ListingDetailScreen({super.key, required this.listingId});

  final String listingId;

  @override
  State<ListingDetailScreen> createState() => _ListingDetailScreenState();
}

class _ListingDetailScreenState extends State<ListingDetailScreen> {
  final StayListingService _service = StayListingService.instance;

  late Future<StayListing?> _listing;
  late Future<List<StayReview>> _reviews;

  /// The guest's own rate. Cached in the service, so this costs one call the
  /// first time Short Stay is opened and nothing after that.
  StayCashbackRate _rate = StayCashbackRate.unknown;

  // ⚠ ADDED 30 September 2026, per Mian — "how do the 4 or 5 pictures
  // display, in demo listing it is only showing 1". The gallery below was
  // already a swipeable PageView over every photo in listing.photos, but it
  // had no dots or any other hint that there was more than one photo to see
  // — so even a listing with several photos read as having just one. This
  // tracks which page the gallery is on so dots can be drawn under it.
  //
  // A ValueNotifier, not setState: setState here would rebuild the WHOLE
  // listing page — map, reviews, days out — on every swipe. Only the dots
  // listen to this.
  final ValueNotifier<int> _photoPage = ValueNotifier<int>(0);

  // ── ⚠ DAYS OUT WERE INVISIBLE UNTIL AFTER YOU BOOKED. 29 August 2026. ─────
  //
  //  StayRoutes.daysOut was pushed from exactly ONE place in the whole app:
  //  15_trip_detail_screen, which a guest reaches only once a booking exists.
  //
  //  So the entire attractions pipeline — the Overpass build, the clustering,
  //  the partner counts, the photographs somebody is now choosing by hand —
  //  was reserved for people who had already committed. The one thing that
  //  answers "why book through GoOuts rather than anywhere else" was being
  //  shown only to people who had already decided.
  //
  //  It belongs here, on the screen where somebody is deciding.
  //
  //  ⚠ COSTS NOTHING EXTRA. forProperty is cached per grid cell in the service,
  //  and a cell covers about 28km by 32km: the second property somebody opens
  //  in Birmingham reads no document at all.
  StayAttractions? _attractions;
  String? _attractionsFor;

  /// ⚠ KEYED ON THE PROPERTY, NOT THE TOWN. It used to be the town name, which
  /// meant two properties in different parts of one city looked identical to
  /// this guard even though they now read different grid cells.
  ///
  /// ⚠ AND IT TAKES THE LISTING, NOT THE ADDRESS. lat and lng live on
  /// StayListing; StayAddress holds only line1, town, postcode and country.
  /// Reaching for listing.address.lat is the obvious guess and it is wrong.
  void _ensureAttractions(StayListing listing) {
    final String key =
        '${listing.lat ?? ''}|${listing.lng ?? ''}|${listing.address.town}';
    if (key == '||') return;
    if (_attractionsFor == key) return;
    _attractionsFor = key;
    StayAttractionsService.instance
        .forProperty(
      lat: listing.lat,
      lng: listing.lng,
      town: listing.address.town,
    )
        .then((StayAttractions? a) {
      if (!mounted) return;
      setState(() => _attractions = a);
    }).catchError((_) {
      // A day out panel that cannot load is a missing panel, not an error on a
      // screen somebody is trying to book from.
      return null;
    });
  }

  @override
  void dispose() {
    _photoPage.dispose();
    super.dispose();
  }

  @override
  void initState() {
    super.initState();
    _listing = _service.byId(widget.listingId);
    _reviews = StayReviewService.instance.forListing(widget.listingId);
    _loadRate();

    // ── ⚠ THE ONLY PLACE A VIEW IS RECORDED. Added 27 August 2026. ──────────
    //
    // "Recently viewed" came back to the home screen when it became real. The
    // obvious place to record was the home screen's own onTap — and that would
    // have been wrong, because it is not the only door.
    //
    // Listings open from the home screen AND from search results. Recording at
    // the tap site means a property found by searching never appears in the
    // history, so the section shows only what was already on the front page —
    // which is the least useful possible version of it.
    //
    // This screen is where a listing is actually looked at, whatever route
    // reached it. Deep links and state restoration land here too.
    //
    // Never awaited and never throws: a browsing convenience must not be able
    // to delay or break opening a property.
    StayRecentlyViewed.instance.record(widget.listingId);
  }

  Future<void> _loadRate() async {
    final StayCashbackRate r =
        await StayBookingService.instance.cashbackRate();
    if (!mounted) return;
    setState(() => _rate = r);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      body: FutureBuilder<StayListing?>(
        future: _listing,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          // An id that does not resolve. Reached by a stale saved listing, a
          // property the host has since removed, or a deep link. Says so
          // rather than showing an empty page with a back button.
          final StayListing? listing = snapshot.data;
          if (snapshot.hasError || listing == null) {
            return const _MessageState(
              icon: Icons.search_off,
              title: 'This property is not available',
              message:
                  'It may have been removed by the host. Please go back and '
                  'choose another one.',
            );
          }

          // ── DESKTOP WEB SPLIT. Added 9 September 2026, same pattern as
          //    01_short_stay_home_screen.dart and food_delivery_screen.dart:
          //    a genuinely separate desktop layout gated on kIsWeb + width,
          //    the mobile layout below is untouched.
          final bool desktop =
              kIsWeb && MediaQuery.of(context).size.width >= 900;
          return desktop
              ? _buildDesktopBody(context, listing)
              : _buildMobileBody(context, listing);
        },
      ),
    );
  }

  // ⚠ ADDED 24 September 2026, per Mian — "listing is not showing properly".
  // Reproduced live: a guest opens a real listing and sees only the price
  // and Check availability button, nothing else — no title, no photos, no
  // description, nothing. There was no visible error anywhere: not in the
  // browser console, not on screen. This screen builds ~15 sections as
  // direct synchronous calls inside one Column's children list
  // (_buildHeader(listing), _buildAboutSection(listing), etc.) — if ANY ONE
  // of them throws for something specific to one listing's data (a field
  // shaped differently than the others, for instance), that single
  // exception takes the WHOLE Column down with it, and a release web build
  // shows nothing at all where debug mode would show Flutter's red error
  // screen. That silence is exactly why this was hard to pin down from the
  // live site.
  //
  // This wraps every section in its own guard. One section failing now
  // costs that section, not the entire page — everything else a guest
  // could still read and still book from keeps working. It also does the
  // one thing that was missing before: logs the label and the real error to
  // the browser console (debugPrint, not swallowed), so if this happens
  // again the exact section and exception are visible in DevTools instead
  // of a page that just looks empty.
  Widget _safe(String label, Widget Function() build) {
    try {
      return build();
    } catch (e, st) {
      debugPrint('ListingDetailScreen: "$label" section failed to build: $e');
      debugPrintStack(stackTrace: st, label: 'ListingDetailScreen/$label');
      return const SizedBox.shrink();
    }
  }

