  static String _miles(double mi) =>
      '${mi.toStringAsFixed(1)} ${mi == 1.0 ? 'mile' : 'miles'}';

  Widget _buildStationItem(StayStation station) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(Icons.train, color: GoOutsColors.primaryBlue, size: 20),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(station.name,
                    style: GoogleFonts.inter(
                        fontSize: 15, fontWeight: FontWeight.w600)),
                if (station.lines.isNotEmpty)
                  Text(station.lines.join(', '),
                      style: GoogleFonts.inter(
                          fontSize: 13.5, color: GoOutsColors.bodyText)),
                Text('${_miles(station.walkMi)} walking',
                    style: GoogleFonts.inter(
                        fontSize: 13.5, fontWeight: FontWeight.w500)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ── The GoOuts difference ────────────────────────────────────────────────
  //
  // The one thing on this screen no competitor can show, so it must be true.
  // Counts come from partnerCounts, and the breakdown is built from the
  // categories actually present rather than the fixed "6 restaurants, 3 pubs,
  // 2 cafes, 3 shops" that used to be printed under every property.
  Widget _buildPartnerHighlightCard(StayLocationContext ctx) {
    final int half = ctx.partnerCounts.halfMile;
    if (half <= 0) return const SizedBox.shrink();

    final List<MapEntry<String, int>> byCategory =
        ctx.partnerCounts.byCategory.entries.where((e) => e.value > 0).toList()
          ..sort((a, b) => b.value.compareTo(a.value));

    final String breakdown = byCategory
        .take(4)
        .map((e) => '${e.value} ${e.key}')
        .join(', ');

    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: GoOutsColors.primaryBlue,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '$half GoOuts ${half == 1 ? 'partner' : 'partners'} '
            'within half a mile',
            style: GoogleFonts.inter(
              fontSize: 15,
              fontWeight: FontWeight.w700,
              color: Colors.white,
            ),
          ),
          if (breakdown.isNotEmpty) ...[
            const SizedBox(height: 12),
            Text(
              breakdown,
              style: GoogleFonts.inter(
                  fontSize: 15, color: Colors.white.withValues(alpha: 0.9)),
            ),
          ],
          const SizedBox(height: 12),
          Text(
            'Earn cashback at every one',
            style: GoogleFonts.inter(
              fontSize: 15,
              fontWeight: FontWeight.w600,
              color: Colors.white,
            ),
          ),
        ],
      ),
    );
  }

  // ── Reviews ──────────────────────────────────────────────────────────────
  //
  // Was one invented review from "Emma • July 2024" shown on every property.
  //
  // ⚠ REAL AS OF 29 August 2026. Reviews are now written by real guests after
  // a stay, through screen 25 and functions/stay_reviews.js. Until that day
  // NOTHING ON THE PLATFORM COULD CREATE ONE — this section, the rating chip
  // on screen 02 and the "Rating" sort order were all reading a subcollection
  // that only the demo seed had ever written to, so every genuinely listed
  // property was going to sit at zero stars for ever.
  // ── Cancellation ─────────────────────────────────────────────────────────
  //
  //  ⚠ THIS SCREEN DID NOT MENTION CANCELLATION AT ALL until 29 August 2026.
  //
  //  Every listing carries a cancellationPolicy, the host chooses it in step 7
  //  of the wizard, there is a whole refund engine behind it — quoteStayCancellation,
  //  cancelStayBooking, screens 28 and 29 — and a guest deciding to spend £165
  //  a night could not find out whether they could get any of it back. They
  //  learned the policy AFTER booking, on the cancel screen.
  //
  //  ⚠ NO PERCENTAGES AND NO DATES HERE, DELIBERATELY. The tiers live in
  //  platform_config/short_stay and are read SERVER side; the enum's own
  //  comment says "a refund amount is NEVER computed on the client". Printing
  //  "free until 48 hours before" from a client that does not hold the numbers
  //  is how a screen ends up contradicting the refund it later gives.
  //
  //  So this names the policy and says where the real figure comes from. The
  //  exact amount appears on screen 28, quoted by the server, before anybody
  //  confirms anything.

  Widget _buildCancellationSection(StayListing listing) {
    final CancellationPolicy p = listing.cancellationPolicy;
    final (IconData icon, String meaning) = switch (p) {
      CancellationPolicy.flexible => (
          Icons.event_available_outlined,
          'The most forgiving of the three. Cancel well before you arrive and '
              'you get the most back.',
        ),
      CancellationPolicy.moderate => (
          Icons.event_note_outlined,
          'A middle tier. How much comes back depends on how close to arrival '
              'you cancel.',
        ),
      CancellationPolicy.strict => (
          Icons.event_busy_outlined,
          'The firmest of the three. Cancelling close to arrival returns '
              'little or nothing.',
        ),
    };

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Divider(height: 32),
        Text(
          'Cancellation',
          style: GoogleFonts.inter(
              fontSize: 15,
              height: 20 / 15,
              fontWeight: FontWeight.w700,
              letterSpacing: 0.3,
              color: GoOutsColors.deepNavy),
        ),
        const SizedBox(height: 12),
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, size: 20, color: GoOutsColors.tealSecondary),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '${p.label} cancellation',
                    style: GoogleFonts.inter(
                        fontSize: 14,
                        height: 20 / 14,
                        fontWeight: FontWeight.w600,
                        color: GoOutsColors.deepNavy),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    meaning,
                    style: GoogleFonts.inter(
                        fontSize: 13.5,
                        height: 1.45,
                        color: GoOutsColors.bodyText),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    // ⚠ SAYS WHERE THE REAL NUMBER COMES FROM rather than
                    // guessing at it. See the note above.
                    'You will see exactly what is refundable, to the penny, '
                    'before you confirm anything.',
                    style: GoogleFonts.inter(
                        fontSize: 12,
                        height: 1.45,
                        color: GoOutsColors.bodyText),
                  ),
                ],
              ),
            ),
          ],
        ),
      ],
    );
  }

  // ── Days out ─────────────────────────────────────────────────────────────
  //
  //  See the note on _attractions. This was reachable only after booking.
  //
  //  ⚠ RENDERS NOTHING AT ALL WHEN THE CITY IS NOT BUILT, rather than an empty
  //  "Days out" heading. On a screen somebody is deciding to spend money from,
  //  a section that announces itself and then has nothing in it reads as a
  //  broken app, and a plain absence reads as nothing.
  Widget _buildDaysOutSection(StayListing listing) {
    _ensureAttractions(listing);

    final StayAttractions? a = _attractions;
    if (a == null || a.clusters.isEmpty) return const SizedBox.shrink();

    final List<StayCluster> nearest = StayAttractionsService.nearest(
      a.clusters,
      listing.lat,
      listing.lng,
    ).take(3).toList();
    if (nearest.isEmpty) return const SizedBox.shrink();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Divider(height: 32),
        Row(
          children: [
            Expanded(
              child: Text(
                'Days out from here',
                style: GoogleFonts.inter(
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                    color: GoOutsColors.deepNavy),
              ),
            ),
            if (a.clusters.length > nearest.length)
              TextButton(
                onPressed: () => Navigator.of(context).pushNamed(
                  StayRoutes.daysOut,
                  arguments: <String, dynamic>{
                    'listingId': listing.id,
                    // Browsing, not travelling. Lights Search rather than
                    // Trips on the bottom bar of the screens beyond this one.
                    'fromListing': true,
                  },
                ),
                style: TextButton.styleFrom(
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  minimumSize: const Size(0, 32),
                ),
                child: Text('See all ${a.clusters.length}',
                    style: GoogleFonts.inter(
                        fontSize: 13.5,
                        fontWeight: FontWeight.w600,
                        color: GoOutsColors.primaryBlue)),
              ),
          ],
        ),
        const SizedBox(height: 4),
        Text(
          // ⚠ MILES, NEVER MINUTES. Same rule as screens 07, 08 and 09: we
          // have no routing API, so a journey time would be invented on a
          // screen somebody plans an afternoon around.
          'Grouped by what you can do in one trip, nearest first.',
          style: GoogleFonts.inter(
              fontSize: 13.5, height: 1.4, color: GoOutsColors.bodyText),
        ),
        const SizedBox(height: 12),
        SizedBox(
          height: 176,
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            itemCount: nearest.length,
            separatorBuilder: (_, __) => const SizedBox(width: 12),
            itemBuilder: (_, i) => _daysOutCard(listing, nearest[i]),
          ),
        ),
      ],
    );
  }

  Widget _daysOutCard(StayListing listing, StayCluster c) {
    final double? mi = (listing.lat != null && listing.lng != null)
        ? StayAttractionsService.milesBetween(
            listing.lat!, listing.lng!, c.lat, c.lng)
        : null;

    return SizedBox(
      width: 208,
      child: Material(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
        clipBehavior: Clip.antiAlias,
        child: InkWell(
          onTap: () => Navigator.of(context).pushNamed(
            StayRoutes.cluster,
            arguments: <String, dynamic>{
              'listingId': listing.id,
              'clusterId': c.id,
              'fromListing': true,
            },
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                height: 96,
                width: double.infinity,
                child: c.photo == null
                    ? Container(
                        color: GoOutsColors.dividerGray,
                        child: const Icon(Icons.museum_outlined,
                            color: GoOutsColors.outlineVariant),
                      )
                    : Image.network(
                        c.photo!.url,
                        fit: BoxFit.cover,
                        cacheWidth: 440,
                        errorBuilder: (_, __, ___) => Container(
                          color: GoOutsColors.dividerGray,
                          child: const Icon(Icons.museum_outlined,
                              color: GoOutsColors.outlineVariant),
                        ),
                      ),
              ),
              Padding(
                padding: const EdgeInsets.all(10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      c.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: GoogleFonts.inter(
                          fontSize: 14,
                          fontWeight: FontWeight.w600,
                          color: GoOutsColors.deepNavy),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      <String>[
                        if (mi != null) '${mi.toStringAsFixed(1)} miles',
                        if (c.partnerCount > 0)
                          '${c.partnerCount} partners',
                      ].join('  ·  '),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: GoogleFonts.inter(
                          fontSize: 12, color: GoOutsColors.bodyText),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildReviewsSection(StayListing listing) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            const Icon(Icons.star, color: GoOutsColors.warning, size: 20),
            const SizedBox(width: 8),
            Text(
              listing.ratingCount > 0
                  ? '${listing.ratingAvg.toStringAsFixed(1)} • '
                      '${_plural(listing.ratingCount, 'review')}'
                  : 'Reviews',
              style:
                  GoogleFonts.inter(fontSize: 15, fontWeight: FontWeight.w700),
            ),
          ],
        ),
        _categoryBreakdown(listing),
        const SizedBox(height: 8),
        FutureBuilder<List<StayReview>>(
          future: _reviews,
          builder: (context, snap) {
            if (snap.connectionState == ConnectionState.waiting) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 16),
                child: Center(child: CircularProgressIndicator()),
              );
            }
            final List<StayReview> reviews =
                snap.data ?? const <StayReview>[];
            if (reviews.isEmpty) {
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 8),
                child: Text(
                  'No reviews yet. Be the first to stay here.',
                  style: GoogleFonts.inter(
                      fontSize: 15, color: GoOutsColors.bodyText),
                ),
              );
            }
            return Column(
              children: [
                for (final r in reviews) _reviewTile(r),
              ],
            );
          },
        ),
      ],
    );
  }

  /// The six category averages, as bars.
  ///
  /// ⚠ THIS EXISTS BECAUSE THE DATA DOES. submitStayReview aggregates the six
  /// sub scores onto the listing, and screen 25 asks a guest for all six. Had
  /// nothing displayed them, this would have been the fourth thing in Short
  /// Stay collected from a person and then never shown to anybody — which is
  /// the pattern the whole review loop was found by.
  ///
  /// ⚠ SKIPS A CATEGORY WITH TOO FEW ANSWERS rather than showing it at zero.
  /// The scores are optional; one guest who disliked the parking must not put
  /// "Location 2.0" under a property nobody else remarked on.
  Widget _categoryBreakdown(StayListing listing) {
    final Map<String, StayCategoryRating> cats = listing.ratingCategories;
    final List<MapEntry<String, String>> shown = _categoryLabels.entries
        .where((e) => cats[e.key]?.hasEnough == true)
        .toList();
    if (shown.isEmpty) return const SizedBox.shrink();

    return Padding(
      padding: const EdgeInsets.only(top: 12),
      child: Column(
        children: [
          for (final MapEntry<String, String> e in shown)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 3),
              child: Row(
                children: [
                  SizedBox(
                    width: 110,
                    child: Text(e.value,
                        style: GoogleFonts.inter(
                            fontSize: 13.5, color: GoOutsColors.bodyText)),
                  ),
                  Expanded(
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(3),
                      child: LinearProgressIndicator(
                        value: cats[e.key]!.avg / 5,
                        minHeight: 5,
                        backgroundColor: GoOutsColors.dividerGray,
                        valueColor: const AlwaysStoppedAnimation<Color>(
                            GoOutsColors.primaryBlue),
                      ),
                    ),
                  ),
                  const SizedBox(width: 10),
                  SizedBox(
                    width: 26,
                    child: Text(
                      cats[e.key]!.avg.toStringAsFixed(1),
                      textAlign: TextAlign.right,
                      style: GoogleFonts.inter(
                          fontSize: 13.5,
                          fontWeight: FontWeight.w600,
                          color: GoOutsColors.deepNavy),
                    ),
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

  /// ⚠ THE KEYS MATCH stay_reviews.js CATEGORIES AND screen 25's
  /// kReviewCategories. Three places, one list. A seventh category added to
  /// the form without being added here is collected and never shown.
  static const Map<String, String> _categoryLabels = <String, String>{
    'cleanliness': 'Cleanliness',
    'accuracy': 'Accuracy',
    'checkIn': 'Check in',
    'communication': 'Communication',
    'location': 'Location',
    'value': 'Value',
  };

  /// ⚠ NOW SHOWS THE STARS. This tile rendered a name, a month and the text
  /// and never once drew the rating, on the screen whose whole heading is
  /// "4.8 · 12 reviews". A reader could see the average and could read the
  /// words, and could not tell which review was the two.
  Widget _reviewTile(StayReview r) {
    final String subtitle = r.createdAt == null
        ? r.guestName
        : '${r.guestName} • ${_monthYear(r.createdAt!)}';

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 10),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const CircleAvatar(
              radius: 18, backgroundColor: GoOutsColors.paleBlueTint),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(subtitle,
                    style: GoogleFonts.inter(
                        fontSize: 14,
                        fontWeight: FontWeight.w600,
                        color: GoOutsColors.deepNavy)),
                const SizedBox(height: 2),
                Row(
                  children: [
                    for (int i = 1; i <= 5; i++)
                      Icon(
                        i <= r.rating
                            ? Icons.star_rounded
                            : Icons.star_border_rounded,
                        size: 14,
                        color: i <= r.rating
                            ? GoOutsColors.warning
                            : GoOutsColors.starGray,
                      ),
                  ],
                ),
                if (r.hasComment) ...[
                  const SizedBox(height: 4),
                  Text(r.comment,
                      style: GoogleFonts.inter(
                          fontSize: 13.5,
                          height: 20 / 13.5,
                          color: GoOutsColors.bodyText)),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  static String _monthYear(DateTime d) =>
      '${_months[d.month - 1]} ${d.year}';

  // ── House rules, check-in and check-out ───────────────────────────────────
  //
  // ⚠ ADDED 27 August 2026: "there is no rules shows to consumer check in and
  // check out".
  //
  // Nothing anywhere in the product carried these. The Stitch GUEST screens
  // displayed them — trip detail draws "Check in 15:00 / Check out 11:00" and a
  // House rules row — but no Stitch HOST screen ever asked for them. Stitch's
  // host step 7 is called "pricing_rules" and its rules are the CANCELLATION
  // policy. So the design showed guest data the design never collected, and
  // 15_trip_detail_screen.dart recorded exactly that on 17 August and left the
  // section out rather than invent a check-in time for somebody's holiday.
  //
  // Fixed at the source: host wizard step 7 now captures it, createStayListing
  // validates and stores it, StayListing parses it with the UK norm as the
  // default for every listing written before today.
  //
  // ⚠ SHOWN BEFORE BOOKING, ON PURPOSE. "No pets" is something a guest needs
  // while they are deciding, not an unpleasant surprise on the confirmation.
  //
  // ⚠ arrivalInstructions IS DELIBERATELY NOT HERE. Door codes and key safe
  // locations belong to a confirmed booking, not to a public listing page that
  // anybody can open.
  Widget _buildHouseRules(StayListing listing) {
    final StayHouseRules r = listing.houseRules;

    TextStyle head() => GoogleFonts.inter(
        fontSize: 15,
        height: 20 / 15,
        fontWeight: FontWeight.w700,
        letterSpacing: 0.3,
        color: GoOutsColors.deepNavy);

    Widget row(IconData icon, String label, String value, {Color? tone}) =>
        Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Icon(icon, size: 18, color: tone ?? GoOutsColors.primaryBlue),
              const SizedBox(width: 12),
              Expanded(
                child: Text(label,
                    style: GoogleFonts.inter(
                        fontSize: 13.5,
                        height: 20 / 13.5,
                        color: GoOutsColors.bodyText)),
              ),
              Text(value,
                  style: GoogleFonts.inter(
                      fontSize: 14,
                      height: 20 / 14,
                      fontWeight: FontWeight.w600,
                      color: tone ?? GoOutsColors.deepNavy)),
            ],
          ),
        );

    // A permission the host has NOT granted is the ordinary case and is drawn
    // plainly. Only what they HAVE allowed is worth colouring, because that is
    // the surprising, useful information.
    Widget permission(IconData icon, String label, bool allowed) => row(
          icon,
          label,
          allowed ? 'Allowed' : 'Not allowed',
          tone: allowed ? GoOutsColors.success : GoOutsColors.bodyText,
        );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        const Divider(height: 32),
        Text('House rules', style: head()),
        const SizedBox(height: 12),

        // Always shown. Every listing has these two, defaulted to the UK norm
        // when the host left the step alone, so there is no empty state.
        row(Icons.login_rounded, 'Check-in from', listing.checkInTime),
        row(Icons.logout_rounded, 'Check-out by', listing.checkOutTime),

        // Hidden entirely when the host said nothing beyond the defaults.
        // Printing three "Not allowed" lines a host never actually chose would
        // put words in their mouth.
        if (!r.isUnset) ...<Widget>[
          const SizedBox(height: 2),
          permission(Icons.smoking_rooms_outlined, 'Smoking',
              r.smokingAllowed),
          permission(Icons.pets_outlined, 'Pets', r.petsAllowed),
          permission(Icons.celebration_outlined, 'Parties or events',
              r.partiesAllowed),
          if (r.hasQuietHours)
            row(Icons.bedtime_outlined, 'Quiet hours',
                '${r.quietHoursFrom} – ${r.quietHoursTo}'),
          if (r.additional.isNotEmpty) ...<Widget>[
            const SizedBox(height: 4),
            Text(r.additional,
                style: GoogleFonts.inter(
                    fontSize: 13.5,
                    height: 20 / 13.5,
                    color: GoOutsColors.bodyText)),
          ],
        ],
      ],
    );
  }

  // ── "Where you'll be" ─────────────────────────────────────────────────────
  //
  // ⚠ THIS SECTION WAS NEVER BUILT. Added 27 August 2026, reported as "there is
  // no map showing in the listing".
  //
  // Stitch draws it between Reviews and the booking bar, captioned with the
  // town. Every other section on this screen was built — gallery, about,
  // amenities, getting around, partner highlight, reviews — and this one was
  // simply skipped. The coordinates were already on the model (`lat`, `lng`,
  // both nullable), already parsed from the `geo` map, and nothing read them.
  //
  // The only GoogleMap in the entire Short Stay feature was on screen 04.
  //
  // ── ⚠ A CIRCLE, NOT A PIN. THIS IS DELIBERATE. ──────────────────────────────
  //
  // The exact address of somebody's home is not shown to a person who has not
  // booked it. This draws a 300m circle around the property and NO marker, so
  // the guest learns the area — which is what they are actually deciding on —
  // without the screen publishing where a host lives to anyone who opens a
  // listing. Every established stay platform does exactly this, and reversing
  // it would be a host-safety problem, not a design tweak.
  //
  // ── ⚠ THE MAP IS DEAD. NO GESTURES, NO CONTROLLER, NO DISPOSE. ─────────────
  //
  // 04_map_results carries a rule at the top of the file: "ONE GoogleMap alive
  // at a time across the whole Short Stay feature, and the controller is
  // disposed". A live, gesture-enabled map inside a scrolling list would break
  // that rule AND fight the ListView for vertical drags.
  //
  // So: every gesture flag off, no onMapCreated, no controller held, therefore
  // nothing to dispose. Lite mode on Android renders it as a static bitmap,
  // which is far cheaper again. Tapping opens the neighbourhood screen, which
  // is the interactive one.
  Widget _buildWhereYoullBe(StayListing listing) {
    final double? lat = listing.lat;
    final double? lng = listing.lng;

    // Hidden entirely when the property has no coordinates. An empty grey box
    // captioned "Where you'll be" is worse than no section: it reads as a
    // failure to load rather than as an absence of data.
    if (lat == null || lng == null) return const SizedBox.shrink();

    final LatLng centre = LatLng(lat, lng);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        const Divider(height: 32),
        Text(
          "Where you'll be",
          style: GoogleFonts.inter(
            fontSize: 15,
            height: 20 / 15,
            fontWeight: FontWeight.w700,
            letterSpacing: 0.3,
            color: GoOutsColors.deepNavy,
          ),
        ),
        const SizedBox(height: 12),
        ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: SizedBox(
            height: 180,
            width: double.infinity,
            child: Stack(
              children: <Widget>[
                GoogleMap(
                  initialCameraPosition:
                      CameraPosition(target: centre, zoom: 14),
                  // Android only. Renders a non-interactive bitmap instead of a
                  // full map surface — a fraction of the memory and no texture
                  // for the ListView to composite on every frame.
                  liteModeEnabled: Theme.of(context).platform ==
                      TargetPlatform.android,
                  circles: <Circle>{
                    Circle(
                      circleId: const CircleId('approx'),
                      center: centre,
                      radius: 300,
                      fillColor:
                          GoOutsColors.primaryBlue.withValues(alpha: 0.18),
                      strokeColor: GoOutsColors.primaryBlue,
                      strokeWidth: 2,
                    ),
                  },
                  // ⚠ Everything off. See the note above about the ListView.
                  zoomControlsEnabled: false,
                  zoomGesturesEnabled: false,
                  scrollGesturesEnabled: false,
                  rotateGesturesEnabled: false,
                  tiltGesturesEnabled: false,
                  myLocationButtonEnabled: false,
                  myLocationEnabled: false,
                  mapToolbarEnabled: false,
                  compassEnabled: false,
                ),
                // ── ⚠ NOW TAPPABLE. 29 August 2026. ────────────────────────
                //
                // This carried a note saying there was deliberately no tap
                // handler, because StayRoutes.neighbourhood resolved to
                // `const NeighbourhoodScreen()` — no listingId, in front of an
                // Unsplash photograph with fake pins on it — so tapping would
                // have sent a guest to an empty screen about nowhere.
                //
                // The note ended "wire this when that screen takes a property".
                // It does now, and this is the most valuable place to open it
                // from: a guest deciding BETWEEN properties is exactly who
                // cares which one has fourteen cashback partners round it.
                //
                // ⚠ A TRANSPARENT OVERLAY, not onTap on the map. Every gesture
                // on this GoogleMap is disabled so it reads as a picture, and a
                // disabled map still swallows taps aimed at it.
                Positioned.fill(
                  child: Material(
                    color: Colors.transparent,
                    child: InkWell(
                      onTap: () => Navigator.of(context).pushNamed(
                        StayRoutes.neighbourhood,
                        arguments: <String, dynamic>{
                          'listingId': widget.listingId,
                        },
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        const SizedBox(height: 8),
        Text(
          listing.address.publicLabel,
          style: GoogleFonts.inter(
            fontSize: 14,
            height: 20 / 14,
            fontWeight: FontWeight.w600,
            color: GoOutsColors.deepNavy,
          ),
        ),
        const SizedBox(height: 2),
        Text(
          'Exact address is shared once your booking is confirmed.',
          style: GoogleFonts.inter(
            fontSize: 12,
            height: 16 / 12,
            fontWeight: FontWeight.w500,
            color: GoOutsColors.bodyText,
          ),
        ),
      ],
    );
  }

  // ── Bottom bar ───────────────────────────────────────────────────────────
  //
  // Was "£112 nightly / 12 to 14 July" with an empty onPressed. The price is
  // now the property's own; the dates line is gone because no dates have been
  // chosen at this point — choosing them is what the button is for.
  Widget _buildBottomBar(BuildContext context, StayListing listing,
      {bool desktop = false}) {
    final Pence rate = listing.nightlyRate;

    final Widget row = Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              '${rate.compact} nightly',
              style: GoogleFonts.inter(
                  fontSize: 16, fontWeight: FontWeight.w700),
            ),
            if (!listing.cleaningFee.isZero)
              Text(
                '${listing.cleaningFee.compact} cleaning fee',
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.bodyText),
              ),
          ],
        ),
        ElevatedButton(
          onPressed: () => Navigator.of(context).pushNamed(
            StayRoutes.bookingDates,
            arguments: <String, dynamic>{'listingId': listing.id},
          ),
          style: ElevatedButton.styleFrom(
            backgroundColor: GoOutsColors.primaryBlue,
            minimumSize: const Size(180, 52),
            shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(12)),
          ),
          child: Text(
            'Check availability',
            style: GoogleFonts.inter(
                fontSize: 16,
                fontWeight: FontWeight.w600,
                color: Colors.white),
          ),
        ),
      ],
    );

    return Align(
      alignment: Alignment.bottomCenter,
      child: Container(
        padding: EdgeInsets.symmetric(
            horizontal: desktop ? 0 : 16, vertical: 20),
        decoration: BoxDecoration(
          color: Colors.white,
          border:
              Border(top: BorderSide(color: Colors.grey.shade300, width: 0.5)),
        ),
        child: SafeArea(
          top: false,
          // ⚠ Desktop keeps the bar edge-to-edge (a sticky footer, like
          // booking.com's) but centres its CONTENT to the reading column so
          // the price and button line up with the text above them, not with
          // the browser's own edges.
          child: desktop ? DesktopCenter(maxWidth: 1100, child: row) : row,
        ),
      ),
    );
  }
}

/// Full-page message with a way back. Used when the listing cannot be loaded.
class _MessageState extends StatelessWidget {
  const _MessageState({
    required this.icon,
    required this.title,
    required this.message,
  });

  final IconData icon;
  final String title;
  final String message;

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 56, color: GoOutsColors.primaryBlue),
              const SizedBox(height: 16),
              Text(
                title,
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                    color: GoOutsColors.deepNavy),
              ),
              const SizedBox(height: 8),
              Text(
                message,
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 15, color: GoOutsColors.bodyText),
              ),
              const SizedBox(height: 24),
              OutlinedButton(
                onPressed: () => Navigator.of(context).pop(),
                child: const Text('Go back'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
